class ConvIndex2 {
  int y, x;
public:
  ConvIndex2(int _y, int _x) : y(_y), x(_x) {}
  int conv(int _y, int _x) { return _y * x + _x; }
  int prod() { return y * x; }
};
class ConvIndex3 {
  int z, y, x;
public:
  ConvIndex3(int _z, int _y, int _x) : z(_z), y(_y), x(_x) {}
  int conv(int _z, int _y, int _x) { return _z * y * x + _y * x + _x; }
  int prod() { return z * y * x; }
};
```

