vector<pair<int, int>> primeFactorize(int n) {
  vector<pair<int, int>> res;
  for (int a = 2; a * a <= n; ++a) {
    if (n % a == 0) {
      res.push_back({a, 0});
      while (n % a == 0)
        ++res.back().second, n /= a;
    }
  }
  if (n != 1)
    res.push_back({n, 1});
